import { Box, Card, CardContent, Grid, Typography } from "@mui/material";
import React, { useEffect, useRef, useState } from "react";

const ADManagerCards = ({ features, features2 }) => {
  const [visibleIndices, setVisibleIndices] = useState([]);
  const [features1Complete, setFeatures1Complete] = useState(false);
  const cardRefs = useRef([]);

  useEffect(() => {
    const observerOptions = {
      root: null, // Use the viewport as the root
      rootMargin: "200px", // Trigger 200px before the element enters the viewport
      threshold: 0, // Trigger as soon as any part of the element is visible
    };

    const observerCallback = (entries, observer) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          const index = parseInt(entry.target.getAttribute("data-index"), 10);
          setVisibleIndices((prev) => [...prev, index]);
          observer.unobserve(entry.target); // Stop observing once the element is visible
        }
      });
    };

    const observer = new IntersectionObserver(
      observerCallback,
      observerOptions
    );

    // Observe features1 cards
    cardRefs.current.slice(0, features.length).forEach((ref) => {
      if (ref) observer.observe(ref);
    });

    return () => {
      observer.disconnect();
    };
  }, [features.length]);

  useEffect(() => {
    // Check if all features1 cards are visible
    if (visibleIndices.length === features.length && !features1Complete) {
      setFeatures1Complete(true);
    }
  }, [visibleIndices, features.length, features1Complete]);

  useEffect(() => {
    if (features1Complete) {
      const observerOptions = {
        root: null,
        rootMargin: "200px",
        threshold: 0,
      };

      const observerCallback = (entries, observer) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const index = parseInt(entry.target.getAttribute("data-index"), 10);
            setVisibleIndices((prev) => [...prev, index]);
            observer.unobserve(entry.target);
          }
        });
      };

      const observer = new IntersectionObserver(
        observerCallback,
        observerOptions
      );

      // Observe features2 cards
      cardRefs.current.slice(features.length).forEach((ref) => {
        if (ref) observer.observe(ref);
      });

      return () => {
        observer.disconnect();
      };
    }
  }, [features1Complete, features.length]);

  return (
    <Grid container sx={{ py: 5 }}>
      <Grid item container spacing={5} xs={12}>
        {features?.map((item, index) => (
          <Grid
            item
            md={4}
            key={index}
            ref={(el) => (cardRefs.current[index] = el)}
            data-index={index}
            sx={{
              opacity: visibleIndices.includes(index) ? 1 : 0,
              transform: visibleIndices.includes(index)
                ? "translateX(0)"
                : "translateX(-50px)",
              transition: "opacity 0.6s ease, transform 0.6s ease",
              transitionDelay: visibleIndices.includes(index)
                ? `${index * 0.3}s`
                : "0s",
            }}
          >
            <Card
              sx={{
                border: "1px solid #CDCDE0",
                borderRadius: "19px",
                boxShadow: "none",
                height: "100%",
                transition: "border-color 0.3s ease", // Smooth transition
                "&:hover": {
                  borderColor: "#602DE1", // Change the border color on hover
                },
              }}
            >
              <CardContent
                sx={{ display: "flex", flexDirection: "column", gap: 4, p: 4 }}
              >
                <Typography
                  sx={{
                    fontSize: { xs: "20px", lg: "24px" },
                    lineHeight: "24px",
                    fontWeight: 500,
                    color: "#602DE1",
                  }}
                >
                  {item.title}
                </Typography>
                <Typography
                  sx={{
                    fontSize: { xs: "14px", sm: "18px" },
                    lineHeight: { xs: "22px", sm: "30px" },
                    fontWeight: 500,
                    color: "#646271",
                  }}
                >
                  <div
                    dangerouslySetInnerHTML={{
                      __html: `<style>p { margin: 0; }</style>${item.description}`,
                    }}
                  />
                  {/* {item.description} */}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
      {features2 && features1Complete && (
        <Grid item container xs={12}>
          <Grid
            item
            xs={12}
            sx={{ display: "flex", justifyContent: "center", py: 6 }}
          >
            <Typography
              sx={{
                fontSize: { xs: "20px", sm: "25px", md: "28px", lg: "38px" },
                lineHeight: { lg: "73px" },
                fontWeight: 500,
                color: "#201D28",
              }}
            >
              Active Directory workflow
            </Typography>
          </Grid>
          <Grid item container spacing={5} xs={12}>
            {features2?.map((item, index) => (
              <Grid
                item
                md={4}
                key={index}
                ref={(el) => (cardRefs.current[index + features.length] = el)}
                data-index={index + features.length}
                sx={{
                  opacity: visibleIndices.includes(index + features.length)
                    ? 1
                    : 0,
                  transform: visibleIndices.includes(index + features.length)
                    ? "translateX(0)"
                    : "translateX(-50px)",
                  transition: "opacity 0.6s ease, transform 0.6s ease",
                  transitionDelay: visibleIndices.includes(
                    index + features.length
                  )
                    ? `${(index + features.length) * 0.3}s`
                    : "0s",
                }}
              >
                <Card
                  sx={{
                    border: "1px solid #CDCDE0",
                    borderRadius: "19px",
                    boxShadow: "none",
                    height: "100%",
                  }}
                >
                  <CardContent
                    sx={{ display: "flex", flexDirection: "column", gap: 4 }}
                  >
                    <Typography
                      sx={{
                        fontSize: { xs: "18px", md: "20px", lg: "24px" },
                        lineHeight: { lg: "24px" },
                        fontWeight: 500,
                        color: "#602DE1",
                      }}
                    >
                      {item.title}
                    </Typography>
                    <Typography
                      sx={{
                        fontSize: { lg: "18px" },
                        lineHeight: { lg: "30px" },
                        fontWeight: 500,
                        color: "#646271",
                      }}
                    >
                      {item.description}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Grid>
      )}
    </Grid>
  );
};

export default ADManagerCards;
